import com.datastax.oss.driver.api.core.CqlSession;
import com.datastax.oss.driver.api.core.cql.SimpleStatement;
import com.datastax.oss.driver.api.core.consistency.DefaultConsistencyLevel;

public class PacelcAwareDataClient {
    private final CqlSession session;

    public PacelcAwareDataClient(CqlSession session) {
        this.session = session;
    }

    public void writeWithLowLatencyProfile(String userId, String status) {
        // Demonstrating an 'Else -> Latency' choice (PA/EL model)
        // We choose LOCAL_QUORUM to keep latency low while maintaining a degree of consistency
        SimpleStatement statement = SimpleStatement.builder(
                "UPDATE user_status SET status = ? WHERE user_id = ?")
                .addPositionalValues(status, userId)
                .setConsistencyLevel(DefaultConsistencyLevel.LOCAL_QUORUM)
                .build();

        session.execute(statement);
    }
}
